/* ==========================================================================
 * 代码同步（GitHub）
 *
 * 为什么要这个：以前每次改代码都要 Oscar 开着电脑、开着浏览器，我一段段把
 * 代码贴进去，又慢又容易贴错。接上 GitHub 之后，我在本地改好推上去，
 * 网站自己拉下来，整个过程不用他在场。顺带白得一份版本历史，改坏能退回。
 *
 * 两个方向：
 *   拉取（pull）—— GitHub → 网站。日常用这个。
 *   回灌（push）—— 网站 → GitHub。只在对齐基线时用一次。
 *
 * 安全：只动 youfang-core 和 youfang-theme 两个目录，只认白名单后缀，
 * 每次拉取前先把现有文件打包备份到 uploads，保留最近 5 份。
 * ========================================================================== */

const YF_GH_REPO = 'yofangguide-star/youfang-site';

function yf_gh_token() {
	return (string) get_option( 'yf_gh_token' );
}

/** 本地两个目录。键就是仓库里的顶层目录名。 */
function yf_gh_roots() {
	return array(
		'youfang-core'  => WP_PLUGIN_DIR . '/youfang-core',
		'youfang-theme' => get_theme_root() . '/youfang-theme',
	);
}

/** 只写这些后缀，其它一律跳过。 */
function yf_gh_ok_ext( $p ) {
	return (bool) preg_match( '/\.(php|css|js|html|json|txt|md|svg|png|jpg|jpeg|gif|webp|woff2?)$/i', $p );
}

/** 暂时不许覆盖的文件。app.css 本地版本比线上少一段，回灌之前不能盖。 */
function yf_gh_skip() {
	return (array) apply_filters( 'yf_gh_skip', array( 'youfang-theme/assets/app.css' ) );
}

function yf_gh_api( $path, $args = array() ) {
	$t = yf_gh_token();
	if ( ! $t ) {
		return new WP_Error( 'no_token', '还没填 GitHub token' );
	}
	$args = wp_parse_args(
		$args,
		array(
			'timeout' => 45,
			'headers' => array(),
		)
	);
	$args['headers'] = array_merge(
		array(
			'Authorization'        => 'Bearer ' . $t,
			'Accept'               => 'application/vnd.github+json',
			'X-GitHub-Api-Version' => '2022-11-28',
			'User-Agent'           => 'youfang-sync',
		),
		$args['headers']
	);
	return wp_remote_request( 'https://api.github.com' . $path, $args );
}

/** 拉取前先备份，留最近 5 份。 */
function yf_gh_backup() {
	if ( ! class_exists( 'ZipArchive' ) ) {
		return '（这台服务器没有 ZipArchive，跳过备份）';
	}
	$up  = wp_upload_dir();
	$dir = trailingslashit( $up['basedir'] ) . 'yf-backup';
	wp_mkdir_p( $dir );
	$file = $dir . '/code-' . gmdate( 'Ymd-His' ) . '.zip';
	$zip  = new ZipArchive();
	if ( true !== $zip->open( $file, ZipArchive::CREATE ) ) {
		return '（备份失败，没有继续）';
	}
	foreach ( yf_gh_roots() as $name => $root ) {
		if ( ! is_dir( $root ) ) {
			continue;
		}
		$it = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( $root, FilesystemIterator::SKIP_DOTS ) );
		foreach ( $it as $f ) {
			if ( $f->isFile() && yf_gh_ok_ext( $f->getPathname() ) ) {
				$zip->addFile( $f->getPathname(), $name . '/' . ltrim( str_replace( $root, '', $f->getPathname() ), '/\\' ) );
			}
		}
	}
	$zip->close();
	$old = glob( $dir . '/code-*.zip' );
	if ( is_array( $old ) && count( $old ) > 5 ) {
		sort( $old );
		foreach ( array_slice( $old, 0, count( $old ) - 5 ) as $x ) {
			wp_delete_file( $x );
		}
	}
	return basename( $file );
}

/** GitHub → 网站。 */
function yf_gh_pull() {
	$r = yf_gh_api( '/repos/' . YF_GH_REPO . '/zipball/main', array( 'timeout' => 90 ) );
	if ( is_wp_error( $r ) ) {
		return $r;
	}
	if ( 200 !== wp_remote_retrieve_response_code( $r ) ) {
		return new WP_Error( 'http', 'GitHub 返回 ' . wp_remote_retrieve_response_code( $r ) . '：' . wp_remote_retrieve_body( $r ) );
	}
	if ( ! class_exists( 'ZipArchive' ) ) {
		return new WP_Error( 'nozip', '这台服务器没有 ZipArchive，没法解压' );
	}
	$tmp = wp_tempnam( 'yfgh' );
	file_put_contents( $tmp, wp_remote_retrieve_body( $r ) ); // phpcs:ignore
	$zip = new ZipArchive();
	if ( true !== $zip->open( $tmp ) ) {
		wp_delete_file( $tmp );
		return new WP_Error( 'badzip', '下载的包打不开' );
	}

	$backup  = yf_gh_backup();
	$roots   = yf_gh_roots();
	$skip    = yf_gh_skip();
	$written = array();
	$skipped = array();

	for ( $i = 0; $i < $zip->numFiles; $i++ ) {
		$name = $zip->getNameIndex( $i );
		if ( '/' === substr( $name, -1 ) ) {
			continue;
		}
		// zipball 的第一层是 "owner-repo-sha/"，去掉。
		$rel = (string) preg_replace( '#^[^/]+/#', '', $name );
		if ( '' === $rel ) {
			continue;
		}
		$top = strtok( $rel, '/' );
		if ( ! isset( $roots[ $top ] ) || ! yf_gh_ok_ext( $rel ) ) {
			continue;
		}
		if ( in_array( $rel, $skip, true ) ) {
			$skipped[] = $rel;
			continue;
		}
		$dest = $roots[ $top ] . substr( $rel, strlen( $top ) );
		// 防目录穿越。
		if ( 0 !== strpos( wp_normalize_path( $dest ), wp_normalize_path( $roots[ $top ] ) ) ) {
			continue;
		}
		$data = $zip->getFromIndex( $i );
		if ( false === $data ) {
			continue;
		}
		if ( file_exists( $dest ) && md5_file( $dest ) === md5( $data ) ) {
			continue; // 没变就不写。
		}
		wp_mkdir_p( dirname( $dest ) );
		if ( false !== file_put_contents( $dest, $data ) ) { // phpcs:ignore
			$written[] = $rel;
		}
	}
	$zip->close();
	wp_delete_file( $tmp );
	update_option( 'yf_gh_last', array( 'at' => time(), 'n' => count( $written ), 'files' => array_slice( $written, 0, 50 ) ), false );
	return array( 'written' => $written, 'skipped' => $skipped, 'backup' => $backup );
}

/** 网站 → GitHub。只在对齐基线时用。 */
function yf_gh_push( $only = '' ) {
	$out = array( 'ok' => array(), 'fail' => array() );
	foreach ( yf_gh_roots() as $name => $root ) {
		if ( ! is_dir( $root ) ) {
			continue;
		}
		$it = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( $root, FilesystemIterator::SKIP_DOTS ) );
		foreach ( $it as $f ) {
			if ( ! $f->isFile() || ! yf_gh_ok_ext( $f->getPathname() ) ) {
				continue;
			}
			$rel = $name . '/' . ltrim( str_replace( $root, '', wp_normalize_path( $f->getPathname() ) ), '/' );
			if ( $only && false === strpos( $rel, $only ) ) {
				continue;
			}
			$body = array(
				'message' => '从服务器回灌：' . $rel,
				'content' => base64_encode( (string) file_get_contents( $f->getPathname() ) ), // phpcs:ignore
				'branch'  => 'main',
			);
			$cur = yf_gh_api( '/repos/' . YF_GH_REPO . '/contents/' . $rel . '?ref=main' );
			if ( ! is_wp_error( $cur ) && 200 === wp_remote_retrieve_response_code( $cur ) ) {
				$j = json_decode( wp_remote_retrieve_body( $cur ), true );
				if ( ! empty( $j['sha'] ) ) {
					if ( ! empty( $j['content'] ) && base64_decode( str_replace( "\n", '', $j['content'] ) ) === file_get_contents( $f->getPathname() ) ) { // phpcs:ignore
						continue; // 一样就不传。
					}
					$body['sha'] = $j['sha'];
				}
			}
			$r = yf_gh_api(
				'/repos/' . YF_GH_REPO . '/contents/' . $rel,
				array( 'method' => 'PUT', 'body' => wp_json_encode( $body ), 'headers' => array( 'Content-Type' => 'application/json' ), 'timeout' => 60 )
			);
			$code = is_wp_error( $r ) ? 0 : wp_remote_retrieve_response_code( $r );
			if ( in_array( $code, array( 200, 201 ), true ) ) {
				$out['ok'][] = $rel;
			} else {
				$out['fail'][] = $rel . '（' . ( is_wp_error( $r ) ? $r->get_error_message() : $code ) . '）';
			}
		}
	}
	return $out;
}

/* ----- 后台：代码同步 ----- */

add_action(
	'admin_menu',
	function () {
		add_submenu_page( 'yf-settings', '代码同步', '代码同步', 'manage_options', 'yf-sync', 'yf_gh_page' );
	},
	30
);

function yf_gh_page() {
	if ( ! current_user_can( 'manage_options' ) ) {
		return;
	}
	$msg = '';
	if ( isset( $_POST['yf_gh_nonce'] ) && wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['yf_gh_nonce'] ) ), 'yf_gh' ) ) {
		if ( isset( $_POST['yf_gh_token_in'] ) ) {
			$t = trim( sanitize_text_field( wp_unslash( $_POST['yf_gh_token_in'] ) ) );
			if ( '' !== $t ) {
				update_option( 'yf_gh_token', $t, false );
				$msg = '<div class="notice notice-success"><p>token 已保存。</p></div>';
			}
		}
		if ( ! empty( $_POST['yf_gh_do_pull'] ) ) {
			$r = yf_gh_pull();
			if ( is_wp_error( $r ) ) {
				$msg = '<div class="notice notice-error"><p>拉取失败：' . esc_html( $r->get_error_message() ) . '</p></div>';
			} else {
				$msg = '<div class="notice notice-success"><p>拉取完成，更新了 <b>' . count( $r['written'] ) . '</b> 个文件。备份：' . esc_html( $r['backup'] ) . '</p>'
					. ( $r['written'] ? '<p>' . esc_html( implode( '、', array_slice( $r['written'], 0, 30 ) ) ) . '</p>' : '<p>没有文件需要更新。</p>' )
					. ( $r['skipped'] ? '<p>按设置跳过：' . esc_html( implode( '、', $r['skipped'] ) ) . '</p>' : '' ) . '</div>';
			}
		}
		if ( ! empty( $_POST['yf_gh_do_push'] ) ) {
			$only = isset( $_POST['yf_gh_only'] ) ? sanitize_text_field( wp_unslash( $_POST['yf_gh_only'] ) ) : '';
			$r    = yf_gh_push( $only );
			$msg  = '<div class="notice notice-success"><p>回灌完成：成功 <b>' . count( $r['ok'] ) . '</b> 个'
				. ( $r['fail'] ? '，失败 <b>' . count( $r['fail'] ) . '</b> 个：' . esc_html( implode( '、', array_slice( $r['fail'], 0, 10 ) ) ) : '' ) . '</p></div>';
		}
		if ( ! empty( $_POST['yf_gh_newsecret'] ) ) {
			update_option( 'yf_gh_secret', wp_generate_password( 32, false ), false );
			$msg = '<div class="notice notice-success"><p>自动拉取密钥已重新生成。</p></div>';
		}
	}
	$tok  = yf_gh_token();
	$last = get_option( 'yf_gh_last' );
	$sec  = (string) get_option( 'yf_gh_secret' );

	echo '<div class="wrap"><h1>代码同步</h1>';
	echo wp_kses_post( $msg );
	echo '<p>仓库：<b>' . esc_html( YF_GH_REPO ) . '</b>　分支：<b>main</b></p>';
	if ( is_array( $last ) ) {
		echo '<p>上次拉取：<b>' . esc_html( wp_date( 'Y-m-d H:i', (int) $last['at'] ) ) . '</b>，更新了 ' . (int) $last['n'] . ' 个文件。</p>';
	}

	echo '<form method="post">';
	wp_nonce_field( 'yf_gh', 'yf_gh_nonce' );

	echo '<h2>1. GitHub token</h2>';
	echo '<p>' . ( $tok ? '已填（' . esc_html( substr( $tok, 0, 7 ) ) . '…），要换就填新的：' : '<b>还没填。</b>' ) . '</p>';
	echo '<p><input type="password" name="yf_gh_token_in" class="regular-text" autocomplete="off" placeholder="github_pat_..."> ';
	submit_button( '保存 token', 'secondary', 'submit', false );
	echo '</p>';
	echo '<p class="description">在 GitHub → Settings → Developer settings → Personal access tokens → <b>Fine-grained tokens</b> 生成，'
		. 'Repository access 选 <b>' . esc_html( YF_GH_REPO ) . '</b>，Permissions 里 <b>Contents</b> 给 <b>Read and write</b>。</p>';

	echo '<hr><h2>2. 从 GitHub 拉取（日常用这个）</h2>';
	echo '<p class="description">把 GitHub 上的最新代码覆盖到网站。<b>拉取前会自动把现有文件打包备份</b>，保留最近 5 份，在 uploads/yf-backup 里。</p>';
	$skip = yf_gh_skip();
	if ( $skip ) {
		echo '<p class="description">当前跳过不覆盖：<b>' . esc_html( implode( '、', $skip ) ) . '</b></p>';
	}
	echo '<p>';
	echo '<input type="hidden" name="yf_gh_do_pull" value="0">';
	submit_button( '从 GitHub 拉取', 'primary', 'yf_gh_do_pull', false, $tok ? array() : array( 'disabled' => 'disabled' ) );
	echo '</p>';

	echo '<hr><h2>3. 回灌到 GitHub（只在对齐基线时用）</h2>';
	echo '<p class="description">把<b>网站上现在的文件</b>传到 GitHub，覆盖仓库里的版本。用来把线上有、仓库里没有的内容补回去。</p>';
	echo '<p><label>只传路径里包含这段的文件（留空＝全部）：<br><input type="text" name="yf_gh_only" class="regular-text" placeholder="app.css"></label></p>';
	echo '<p>';
	submit_button( '回灌到 GitHub', 'secondary', 'yf_gh_do_push', false, $tok ? array() : array( 'disabled' => 'disabled' ) );
	echo '</p>';

	echo '<hr><h2>4. 自动拉取</h2>';
	if ( $sec ) {
		echo '<p>把这个地址配到 GitHub Actions 里，推代码后网站会自动拉：</p>';
		echo '<p><code style="user-select:all">' . esc_html( rest_url( 'yf/v1/pull' ) . '?key=' . $sec ) . '</code></p>';
	} else {
		echo '<p>还没生成密钥。</p>';
	}
	echo '<p>';
	submit_button( $sec ? '重新生成密钥' : '生成密钥', 'secondary', 'yf_gh_newsecret', false );
	echo '</p></form></div>';
}

/* ----- 自动拉取的接口 ----- */

add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'yf/v1',
			'/pull',
			array(
				'methods'             => 'POST,GET',
				'permission_callback' => '__return_true',
				'callback'            => function ( $req ) {
					$sec = (string) get_option( 'yf_gh_secret' );
					$key = (string) $req->get_param( 'key' );
					if ( ! $sec || ! $key || ! hash_equals( $sec, $key ) ) {
						return new WP_REST_Response( array( 'ok' => false, 'err' => 'bad key' ), 403 );
					}
					$r = yf_gh_pull();
					if ( is_wp_error( $r ) ) {
						return new WP_REST_Response( array( 'ok' => false, 'err' => $r->get_error_message() ), 500 );
					}
					return new WP_REST_Response( array( 'ok' => true, 'written' => count( $r['written'] ), 'skipped' => $r['skipped'] ), 200 );
				},
			)
		);
	}
);
